package com.abhishek.hotelbooking.service.impl; import com.abhishek.hotelbooking.dto.room.RoomRequest; import com.abhishek.hotelbooking.entity.*; import com.abhishek.hotelbooking.exception.ResourceNotFoundException; import com.abhishek.hotelbooking.repository.*; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.*;
@Service public class RoomService { private final RoomRepository rooms; private final HotelRepository hotels; public RoomService(RoomRepository rooms,HotelRepository hotels){this.rooms=rooms;this.hotels=hotels;} public Room create(Long hotelId,RoomRequest r){Hotel h=hotels.findById(hotelId).orElseThrow(()->new ResourceNotFoundException("Hotel not found")); return rooms.save(Room.builder().hotel(h).roomNumber(r.roomNumber()).type(r.type()).pricePerNight(r.pricePerNight()).capacity(r.capacity()).active(true).build());} public List<Room> byHotel(Long hotelId){return rooms.findByHotelIdAndActiveTrue(hotelId);} public List<Room> available(Long hotelId,LocalDate in,LocalDate out){if(!in.isBefore(out))throw new IllegalArgumentException("checkIn must be before checkOut");return rooms.findAvailable(hotelId,in,out);} public Room get(Long id){return rooms.findById(id).orElseThrow(()->new ResourceNotFoundException("Room not found"));} }